#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* Byte-swap mask for little-endian load of big-endian words */
static const uint8_t bswap_mask_bytes[16] __attribute__((aligned(16))) = {
    3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12
};

static const uint32_t K[64] __attribute__((aligned(64))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline __m128i sigma0(__m128i x){
    /* rotr7 ^ rotr18 ^ shr3 */
    return _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(x,7), _mm_ror_epi32(x,18)), _mm_srli_epi32(x,3));
}
static inline __m128i sigma1(__m128i x){
    return _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(x,17), _mm_ror_epi32(x,19)), _mm_srli_epi32(x,10));
}

static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }

static void sha256_block(uint32_t st[8], const uint8_t blk[64]){
    __m128i mask = _mm_load_si128((const __m128i*)bswap_mask_bytes);
    __m128i W0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+0)), mask);
    __m128i W1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+16)), mask);
    __m128i W2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+32)), mask);
    __m128i W3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+48)), mask);

    uint32_t w[64];
    _mm_storeu_si128((__m128i*)(w+0), W0);
    _mm_storeu_si128((__m128i*)(w+4), W1);
    _mm_storeu_si128((__m128i*)(w+8), W2);
    _mm_storeu_si128((__m128i*)(w+12), W3);

    /* expand using SIMD, 4 words at a time, then store */
    __m128i w0=W0, w1=W1, w2=W2, w3=W3;
    for(int i=16;i<64;i+=4){
        /* s0 = sigma0(W[i-15]) = sigma0(w0 lanes 1,2,3 and w1 lane 0) -> alignr */
        __m128i v15 = _mm_alignr_epi8(w1, w0, 4);   /* W[i-15 .. i-12] */
        __m128i v7  = _mm_alignr_epi8(w3, w2, 4);   /* W[i-7 .. i-4]  wait: w2 is W[i-8..i-5], w3 is W[i-4..i-1]
                                                       alignr(w3,w2,4) = W[i-7 .. i-4]. yes */
        __m128i v2  = w3;                            /* W[i-4 .. i-1]; we need W[i-2] which is lanes 2,3 of w3 and ... */
        /* sigma1 needs W[i-2]: alignr of next which we don't have. Use shuffle. */
        /* W[i-2] = lanes: w3[2], w3[3], and the two new words we haven't computed.
           For 4-at-a-time this is the annoying part. Compute scalar for the dependency within the 4.
           Let's just do the standard approach: compute s0 fully (no intra dep), s1 partially. */
        __m128i s0 = sigma0(v15);
        /* For s1, W[i-2] for the first two outputs are known (w3 lanes 2,3 and ... actually:
           output word 0 needs W[i-2] = w3 lane 2
           output word 1 needs W[i-2] = w3 lane 3
           output word 2 needs W[i-2] = new word 0
           output word 3 needs W[i-2] = new word 1
           So do two rounds scalar-vector hybrid: compute first two, then last two.
        */
        /* Extract and compute in scalar for schedule to keep it simple & correct, SIMD for sigma where easy.
           Given store already happened, just compute schedule in scalar — the SIMD load already saved bswap.
           The schedule is ~30% of time. Let's do it vectorially properly.
        */
        (void)s0; (void)v2; (void)v7;
        break;
    }
    for(int i=16;i<64;i++){
        uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15]>>3);
        uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2]>>10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }

    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    #pragma unroll
    for(int i=0;i<64;i++){
        uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
        uint32_t ch = (e&f)^((~e)&g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

void sha256(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t i=0;
    for(; i+64<=len; i+=64) sha256_block(state, data+i);
    uint8_t block[64];
    size_t rem = len-i;
    memset(block,0,64);
    memcpy(block, data+i, rem);
    block[rem]=0x80;
    if(rem>=56){ sha256_block(state, block); memset(block,0,64); }
    uint64_t bits = (uint64_t)len*8;
    for(int j=0;j<8;j++) block[63-j]=(uint8_t)(bits>>(8*j));
    sha256_block(state, block);
    for(int j=0;j<8;j++){
        uint32_t v = __builtin_bswap32(state[j]);
        memcpy(out+4*j,&v,4);
    }
}

int main(){
    size_t n = 20000*1024;
    uint8_t *buf = malloc(n);
    memset(buf, 0x5a, n);
    uint8_t out[32];
    sha256(buf, n, out);
    int iters=5;
    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int i=0;i<iters;i++) sha256(buf,n,out);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("avx-load: %.4f s/iter (%.2f MB/s)\n", dt/iters, (n/1e6)/(dt/iters));
    printf("digest: ");
    for(int i=0;i<32;i++) printf("%02x", out[i]);
    printf("\n");
}
EOF
