#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static const uint8_t bswap_mask_bytes[16] __attribute__((aligned(16))) = {
    3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12
};
static const uint32_t K[64] __attribute__((aligned(64))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline __m128i ror32(__m128i x, int n){
    return _mm_or_si128(_mm_srli_epi32(x, n), _mm_slli_epi32(x, 32-n));
}
static inline __m128i sigma0(__m128i x){
    return _mm_xor_si128(_mm_xor_si128(ror32(x,7), ror32(x,18)), _mm_srli_epi32(x,3));
}
static inline __m128i sigma1(__m128i x){
    return _mm_xor_si128(_mm_xor_si128(ror32(x,17), ror32(x,19)), _mm_srli_epi32(x,10));
}
static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }

/* Expand schedule 4 words at a time. The sigma1 term depends on the two newest
   words, so each group of 4 is done as two vector ops of 2 (low half known). */
static inline __m128i expand4(__m128i w0, __m128i w1, __m128i w2, __m128i w3){
    /* w0 = W[i-16..i-13], w1=W[i-12..i-9], w2=W[i-8..i-5], w3=W[i-4..i-1]
       result = W[i..i+3]
       s0 = sigma0(W[i-15..i-12]) = alignr(w1,w0,4)
       s1 for first 2 words uses W[i-2],W[i-1] (known, lanes 2,3 of w3) and
       for last 2 words uses the newly computed words. We compute all 4 of s0
       and the W[i-7], W[i-16] terms vectorially, then fix s1 in two steps. */
    __m128i v15 = _mm_alignr_epi8(w1, w0, 4);
    __m128i v7  = _mm_alignr_epi8(w3, w2, 4);
    __m128i s0  = sigma0(v15);
    __m128i base = _mm_add_epi32(_mm_add_epi32(w0, s0), v7); /* missing s1 */

    /* s1 for words 0,1: W[i-2] = w3 lane2, W[i-1] = w3 lane3.
       Build a vector whose lanes are W[i-2], W[i-1], ?, ? then sigma1, take low 2. */
    __m128i prev2 = _mm_srli_si128(w3, 8);          /* lanes: W[i-2], W[i-1], 0, 0 */
    __m128i s1_01 = sigma1(prev2);                   /* correct in lanes 0,1 */
    __m128i t = _mm_add_epi32(base, s1_01);          /* lanes 0,1 correct; 2,3 garbage */

    /* Now words 2,3 need sigma1(W[i], W[i+1]) = sigma1(t lanes 0,1).
       Build vector lanes: W[i], W[i+1], 0, 0 = t low 8 bytes, sigma1, place into lanes 2,3. */
    __m128i new01 = _mm_slli_si128(t, 8);            /* lanes: 0,0,W[i],W[i+1]  -- not what we want */
    /* We want lanes 0,1 = W[i],W[i+1]. That's just t (low). sigma1(t) lanes 0,1 are correct
       sigma1 values for words 2,3. Shift them up by 8 bytes and blend. */
    __m128i s1_23_low = sigma1(t);                   /* lanes 0,1 = sigma1(W[i]), sigma1(W[i+1]) */
    __m128i s1_23 = _mm_slli_si128(s1_23_low, 8);    /* lanes 2,3 */
    __m128i mask = _mm_set_epi32(0,0,-1,-1);         /* keep lanes 0,1 from t */
    __m128i s1 = _mm_or_si128(_mm_and_si128(s1_01, mask), s1_23);
    return _mm_add_epi32(base, s1);
}

static void sha256_block(uint32_t st[8], const uint8_t blk[64]){
    __m128i mask = _mm_load_si128((const __m128i*)bswap_mask_bytes);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+0)), mask);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+16)), mask);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+32)), mask);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(blk+48)), mask);

    __m128i wv[16];
    wv[0]=w0; wv[1]=w1; wv[2]=w2; wv[3]=w3;
    for(int r=4;r<16;r++){
        __m128i n = expand4(wv[r-4], wv[r-3], wv[r-2], wv[r-1]);
        wv[r]=n;
    }
    uint32_t w[64];
    for(int r=0;r<16;r++) _mm_storeu_si128((__m128i*)(w+4*r), wv[r]);

