#define ROR(x,n) __builtin_rotateright32((x),(n))

static void compress(uint32_t st[8], const uint8_t blk[64]){
    uint32_t W[64];
    for(int i=0;i<16;i++){
        W[i] = ((uint32_t)blk[4*i]<<24)|((uint32_t)blk[4*i+1]<<16)|((uint32_t)blk[4*i+2]<<8)|(uint32_t)blk[4*i+3];
