#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <mach/mach_time.h>
#include <openssl/sha.h>
typedef struct { const unsigned char *ptr; int blocks; } DESC;
extern void sha256_multi_block(void *ctx, const DESC *inp, int num);

/* transpose: for each group of 8 consecutive blocks, lane l gets block (group*8+l) */
static void transpose8(const unsigned char *in, unsigned char *lanes[8], size_t blocks){
    size_t groups = blocks/8;
    for(size_t g=0; g<groups; g++){
        for(int l=0;l<8;l++){
            memcpy(lanes[l]+g*64, in+(g*8+l)*64, 64);
        }
    }
}
int main(){
    size_t total=20*1024*1024UL;
    size_t blocks=total/64;
    unsigned char *in=malloc(total);
    memset(in,0x5a,total);
    unsigned char *lane_mem=malloc(total);
    unsigned char *lanes[8];
    size_t per=blocks/8*64;
    for(int l=0;l<8;l++) lanes[l]=lane_mem+l*per;
    mach_timebase_info_data_t tb; mach_timebase_info(&tb);
    int iters=3; uint64_t t0=mach_absolute_time();
    for(int i=0;i<iters;i++) transpose8(in,lanes,blocks);
    uint64_t t1=mach_absolute_time();
    double dt=(double)(t1-t0)*tb.numer/tb.denom/1e9;
    printf("transpose: %.4f s (%.1f MB/s)\n", dt/iters, (total/1e6)/(dt/iters));

    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t ctx[64];
    DESC d[8]; for(int l=0;l<8;l++){ d[l].ptr=lanes[l]; d[l].blocks=(int)(per/64); }
    t0=mach_absolute_time();
    for(int i=0;i<iters;i++){
        for(int w=0;w<8;w++) for(int l=0;l<8;l++) ctx[w*8+l]=iv[w];
        sha256_multi_block(ctx,d,2);
    }
    t1=mach_absolute_time();
    dt=(double)(t1-t0)*tb.numer/tb.denom/1e9;
    printf("multi after transpose: %.4f s (%.1f MB/s)\n", dt/iters, (total/1e6)/(dt/iters));
    return 0;
}
EOF
