#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <mach/mach_time.h>
#include <OpenCL/cl.h>
static const char *SRC =
"__constant uint K[64] = {"
"0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,"
"0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,"
"0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,"
"0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,"
"0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,"
"0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,"
"0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,"
"0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};\n"
"#define ROR(x,n) rotate((uint)(x),(uint)(32-(n)))\n"
"static void compress(uint *a0,uint *b0,uint *c0,uint *d0,uint *e0,uint *f0,uint *g0,uint *h0, __global const uchar *p){\n"
"  uint W[64];\n"
"  for(int i=0;i<16;i++) W[i]=((uint)p[4*i]<<24)|((uint)p[4*i+1]<<16)|((uint)p[4*i+2]<<8)|(uint)p[4*i+3];\n"
"  for(int i=16;i<64;i++){ uint x=W[i-15]; uint y=W[i-2];\n"
"    W[i]=W[i-16]+(ROR(x,7)^ROR(x,18)^(x>>3))+W[i-7]+(ROR(y,17)^ROR(y,19)^(y>>10)); }\n"
"  uint a=*a0,b=*b0,c=*c0,d=*d0,e=*e0,f=*f0,g=*g0,h=*h0;\n"
"  for(int i=0;i<64;i++){\n"
"    uint S1=ROR(e,6)^ROR(e,11)^ROR(e,25); uint ch=(e&f)^((~e)&g); uint t1=h+S1+ch+K[i]+W[i];\n"
"    uint S0=ROR(a,2)^ROR(a,13)^ROR(a,22); uint maj=(a&b)^(a&c)^(b&c); uint t2=S0+maj;\n"
"    h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2; }\n"
"  *a0+=a;*b0+=b;*c0+=c;*d0+=d;*e0+=e;*f0+=f;*g0+=g;*h0+=h;\n"
"}\n"
/* Each work-item owns one segment and hashes `blocks` blocks under the incoming state.
   For level 0, states are IV and blocks_per = chunk. For level>0, the host has rearranged
   states so state[i] is the chained state and the segment starts at block offset i*stride. */
"__kernel void seg(__global const uchar *in, __global uint *st, uint blocks, uint stride){\n"
"  uint gid=get_global_id(0);\n"
"  __global uint *s=st+gid*8u;\n"
"  uint a0=s[0],b0=s[1],c0=s[2],d0=s[3],e0=s[4],f0=s[5],g0=s[6],h0=s[7];\n"
"  __global const uchar *base=in+((ulong)gid*stride)*64u;\n"
"  for(uint blk=0; blk<blocks; blk++) compress(&a0,&b0,&c0,&d0,&e0,&f0,&g0,&h0, base+blk*64u);\n"
"  s[0]=a0;s[1]=b0;s[2]=c0;s[3]=d0;s[4]=e0;s[5]=f0;s[6]=g0;s[7]=h0;\n"
"}\n";
#define CHECK(x) do{cl_int _e=(x); if(_e){printf("err %d at %d\n",_e,__LINE__); exit(1);}}while(0)
int main(){
    cl_platform_id plat; cl_uint np; clGetPlatformIDs(1,&plat,&np);
    cl_device_id devs[8]; cl_uint nd; clGetDeviceIDs(plat,CL_DEVICE_TYPE_GPU,8,devs,&nd);
    cl_device_id dev=devs[nd-1]; cl_int err;
    cl_context ctx=clCreateContext(NULL,1,&dev,NULL,NULL,&err); CHECK(err);
    cl_command_queue q=clCreateCommandQueue(ctx,dev,0,&err); CHECK(err);
    cl_program prog=clCreateProgramWithSource(ctx,1,&SRC,NULL,&err); CHECK(err);
    err=clBuildProgram(prog,1,&dev,"-cl-fast-relaxed-math",NULL,NULL);
    if(err){char log[8192]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,8192,log,NULL); printf("%s\n",log); return 1;}
    cl_kernel k=clCreateKernel(prog,"seg",&err); CHECK(err);

    size_t total=20*1024*1024UL; total&=~63UL;
    unsigned char *data=malloc(total); memset(data,0x5a,total);
    int segs=1024;
    cl_uint seg_blocks=(cl_uint)((total/64)/segs);
    size_t used=(size_t)seg_blocks*64*segs;
    cl_mem bin=clCreateBuffer(ctx,CL_MEM_READ_ONLY|CL_MEM_COPY_HOST_PTR,used,data,&err); CHECK(err);
    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t *hst=malloc(segs*32);
    for(int i=0;i<segs;i++) memcpy(hst+i*8,iv,32);
    cl_mem bst=clCreateBuffer(ctx,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,segs*32,hst,&err); CHECK(err);
    uint32_t *tmp=malloc(segs*32);

    mach_timebase_info_data_t tb; mach_timebase_info(&tb);
    int iters=3; uint64_t t0=mach_absolute_time();
    for(int it=0; it<iters; it++){
        clEnqueueWriteBuffer(q,bst,CL_FALSE,0,segs*32,hst,0,NULL,NULL);
        int active=segs; cl_uint span=seg_blocks;
        while(active>=1){
            size_t g=active;
            cl_uint blocks=span, stride=span;
            clSetKernelArg(k,0,sizeof(cl_mem),&bin);
            clSetKernelArg(k,1,sizeof(cl_mem),&bst);
            clSetKernelArg(k,2,sizeof(cl_uint),&blocks);
            clSetKernelArg(k,3,sizeof(cl_uint),&stride);
            clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL);
            if(active==1) break;
            /* read back states, keep even ones (the chained prefix states), compact, write back */
            clEnqueueReadBuffer(q,bst,CL_TRUE,0,active*32,tmp,0,NULL,NULL);
            int nxt=active/2;
            for(int i=0;i<nxt;i++) memcpy(tmp+i*8, tmp+(2*i)*8, 32);
            clEnqueueWriteBuffer(q,bst,CL_FALSE,0,nxt*32,tmp,0,NULL,NULL);
            active=nxt; span*=2;
        }
        clFinish(q);
    }
    uint64_t t1=mach_absolute_time();
    double dt=(double)(t1-t0)*tb.numer/tb.denom/1e9;
    printf("tree (compute+readback each level): %.4f s (%.1f MB/s)\n", dt/iters, (used/1e6)/(dt/iters));
    return 0;
}
