"__kernel void level0(__global const uint16 *in, __global uint *st, uint blocks){\n"
"  uint gid=get_global_id(0);\n"
"  uint S[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};\n"
