"}\n"
/* level>0: lane i hashes `blocks` blocks starting at block offset given per-lane, under st[i] */
"__kernel void leveln(__global const uint16 *in, __global uint *st, __global uint *off, uint blocks){\n"
"  uint gid=get_global_id(0);\n"
"  __global uint *s=st+gid*8u;\n"
