    cl_kernel k0=clCreateKernel(prog,"level0",&err); CHECK(err);
    cl_kernel kn=clCreateKernel(prog,"leveln",&err); CHECK(err);

    size_t total=20*1024*1024UL; total&=~63UL;
    int lanes=256; cl_uint seg=(cl_uint)((total/64)/lanes); size_t bytes=(size_t)seg*64*lanes;
