    cl_mem bst=clCreateBuffer(ctx,CL_MEM_READ_WRITE,lanes*32,NULL,&err); CHECK(err);
    cl_mem boff=clCreateBuffer(ctx,CL_MEM_READ_ONLY,lanes*4,NULL,&err); CHECK(err);
