            clEnqueueReadBuffer(q,bst,CL_TRUE,0,active*32,hst,0,NULL,NULL);
            for(int i=0;i<nxt;i++){ memcpy(hst+i*8, hst+(2*i)*8, 32); hoff[i]=(uint32_t)((2*i+1)*span); }
            clEnqueueWriteBuffer(q,bst,CL_FALSE,0,nxt*32,hst,0,NULL,NULL);
            clEnqueueWriteBuffer(q,boff,CL_FALSE,0,nxt*4,hoff,0,NULL,NULL);
            clSetKernelArg(kn,0,sizeof(cl_mem),&bin);
            clSetKernelArg(kn,1,sizeof(cl_mem),&bst);
            clSetKernelArg(kn,2,sizeof(cl_mem),&boff);
            clSetKernelArg(kn,3,sizeof(cl_uint),&span);
