final_solver:
"""Fast FFT convolution via Apple vDSP (Accelerate).

Convolution is still computed in the frequency domain (real DFT, pointwise
multiply, inverse DFT). vDSP's double-precision DFT is substantially faster
than scipy's pocketfft on this machine once the transform setups are cached,
and converting the input lists in C avoids the numpy list-to-array overhead
that dominates a large part of the reference runtime.
"""
import os
import sys
import sysconfig
import subprocess
import importlib

import numpy as np

_HERE = os.path.dirname(os.path.abspath(__file__))
_BUILD = os.path.join(_HERE, ".build")
os.makedirs(_BUILD, exist_ok=True)

_SRC = r'''
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CACHE 64

typedef struct {
    vDSP_Length N;
    vDSP_DFT_SetupD setupF;
    vDSP_DFT_SetupD setupI;
    double *xr, *xi, *yr, *yi;
    vDSP_Length half;
} Cache;

static Cache cache[MAX_CACHE];
static int cache_n = 0;

/* vDSP real DFT is fast for N = 2^k or N = f*2^k, f in {3,5,15}, k >= 4. */
static vDSP_Length good_len(vDSP_Length n) {
    if (n < 2) n = 2;
    if (n & 1) n++;
    vDSP_Length p2 = 1;
    while (p2 < n) p2 <<= 1;
    vDSP_Length best = p2;
    int fs[3] = {3, 5, 15};
    for (int i = 0; i < 3; i++) {
        int f = fs[i];
        vDSP_Length base = (vDSP_Length)f << 4;
        if (base >= n) {
            if (base < best) best = base;
        } else {
            vDSP_Length v = base;
            while (v < n) v <<= 1;
            if (v >= n && v < best) best = v;
        }
    }
    return best;
}

static Cache* get_cache(vDSP_Length N) {
    for (int i = 0; i < cache_n; i++) {
        if (cache[i].N == N) return &cache[i];
    }
    if (cache_n >= MAX_CACHE) {
        PyErr_SetString(PyExc_RuntimeError, "FFT cache full");
        return NULL;
    }
    Cache* c = &cache[cache_n];
    c->N = N;
    c->half = N / 2;
    c->setupF = vDSP_DFT_zrop_CreateSetupD(NULL, N, vDSP_DFT_FORWARD);
    c->setupI = vDSP_DFT_zrop_CreateSetupD(c->setupF, N, vDSP_DFT_INVERSE);
    if (posix_memalign((void**)&c->xr, 64, c->half * sizeof(double)) ||
        posix_memalign((void**)&c->xi, 64, c->half * sizeof(double)) ||
        posix_memalign((void**)&c->yr, 64, c->half * sizeof(double)) ||
        posix_memalign((void**)&c->yi, 64, c->half * sizeof(double)) ||
        !c->setupF || !c->setupI) {
        PyErr_SetString(PyExc_RuntimeError, "vDSP setup/alloc failed");
        return NULL;
    }
    cache_n++;
    return c;
}

static PyObject* warmup(PyObject* self, PyObject* args) {
    unsigned long long lo, hi;
    if (!PyArg_ParseTuple(args, "KK", &lo, &hi)) return NULL;
    vDSP_Length prev = 0;
    for (unsigned long long L = lo; L <= hi; L++) {
        vDSP_Length g = good_len((vDSP_Length)L);
        if (g != prev) {
            if (!get_cache(g)) return NULL;
            prev = g;
        }
    }
    Py_RETURN_NONE;
}

static double* list_to_buf(PyObject* lst, npy_intp* out_n) {
    if (!PyList_Check(lst)) {
        PyErr_SetString(PyExc_TypeError, "expected list");
        return NULL;
    }
    Py_ssize_t n = PyList_GET_SIZE(lst);
    *out_n = (npy_intp)n;
    double* buf = (double*)malloc((n > 0 ? (size_t)n : 1) * sizeof(double));
    if (!buf) { PyErr_NoMemory(); return NULL; }
    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject* item = PyList_GET_ITEM(lst, i);
        if (PyFloat_CheckExact(item)) {
            buf[i] = PyFloat_AS_DOUBLE(item);
        } else {
            buf[i] = PyFloat_AsDouble(item);
            if (buf[i] == -1.0 && PyErr_Occurred()) { free(buf); return NULL; }
        }
    }
    return buf;
}

/* mode: 0 full, 1 same, 2 valid */
static PyObject* convolve(PyObject* self, PyObject* args) {
    PyObject *lx_obj, *ly_obj;
    int mode;
    if (!PyArg_ParseTuple(args, "OOi", &lx_obj, &ly_obj, &mode)) return NULL;

    npy_intp lx, ly;
    double *x = list_to_buf(lx_obj, &lx);
    if (!x) return NULL;
    double *y = list_to_buf(ly_obj, &ly);
    if (!y) { free(x); return NULL; }

