/* Find a vDSP-friendly length >= n: 2^k, or f*2^k with f in {3,5,15} and k>=4 */
static vDSP_Length good_len(vDSP_Length n) {
    if (n < 2) n = 2;
    if (n & 1) n++;
    /* next power of 2 */
    vDSP_Length p2 = 1;
    while (p2 < n) p2 <<= 1;
    vDSP_Length best = p2;
    int fs[3] = {3, 5, 15};
    for (int i = 0; i < 3; i++) {
        int f = fs[i];
        /* smallest 2^k * f >= n with k>=4 */
        vDSP_Length base = (vDSP_Length)f << 4; /* f*16 */
        if (base >= n && base < best) best = base;
        else if (base < n) {
            vDSP_Length v = base;
            while (v < n) v <<= 1;
            if (v < best) best = v;
        }
    }
    return best;
