    if (!PyArg_ParseTuple(args, "OOi", &lx_obj, &ly_obj, &mode)) return NULL;

    npy_intp lx, ly;
    double *x = list_to_buf(lx_obj, &lx);
    if (!x) return NULL;
    double *y = list_to_buf(ly_obj, &ly);
    if (!y) { free(x); return NULL; }

    if (lx == 0 || ly == 0) {
        free(x); free(y);
        npy_intp dims[1] = {0};
        return PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    }

    /* valid mode: swap so x is the longer signal (matches scipy) */
    if (mode == 2 && ly > lx) {
        double* tmp = x; x = y; y = tmp;
        npy_intp t = lx; lx = ly; ly = t;
    }

