import numpy as np
from scipy.special import wright_bessel
from scipy.integrate import quad
from numba import njit, prange

@njit(parallel=True)
def wright_bessel_numba(x, a, b):
    n = len(x)
    res = np .zeros(n)
    for i in prange(n):
        s = 0.0
        k = 0
        term = 1.0
        while True:
            s += term
            k += 1
            term *= x[i] / (k * np.math.gamma(a[i ] * k + b[i]))
            if abs(term) < 1e-15:
                break
        res[i] = s
    return res

@njit(parallel=True)
def integrate_numba(a, b, lower, upper):
    n = len(a)
    res = np.zeros(n )
    for i in prange(n):
        def integrand(x):
            return wright_bessel_numba(x, a, b)
        res[i] = quad(integrand, lower[i], upper[i], epsabs=1e-12, epsrel=1e-12)[0]
    return res

class Solver:
    def solve(self, problem):
        a = np.array(problem["a"], dtype=np.float64)
        b = np.array(problem["b"], dtype=np.float64)
        lower = np.array(problem["lower"], dtype=np.float64)
        upper = np.array(problem["upper"], dtype=np.float64)
        result = integrate_numba(a, b, lower, upper)
        return {"result": result.tolist()}
