#include <math.h>
#include <stdlib.h>
#include <string.h>

/* Contiguous-layout Levinson. Compiled with clang -O3 -ffast-math -mavx2 -mfma. */
void solve_toep(const double* c, const double* r, const double* b, double* x, int n) {
    double* f = (double*)malloc(n*sizeof(double));
    double* st = (double*)malloc(n*sizeof(double));
    double* st_rev = (double*)malloc(n*sizeof(double));
    double* f_rev = (double*)malloc(n*sizeof(double));
    double* x_rev = (double*)malloc(n*sizeof(double));
    double* buf = (double*)malloc(n*sizeof(double));

    double d0 = r[0];
    x[0] = b[0]/d0;
    f[0] = 1.0/d0;
    if (n==1){ free(f);free(st);free(st_rev);free(f_rev);free(x_rev);free(buf); return; }
    st[0] = r[1]/d0;
    st_rev[0]=st[0]; f_rev[0]=f[0]; x_rev[0]=x[0];

    for (int k=1; k<n; k++){
        double vp=0, vf=0, vx=0;
        for (int i=0;i<k;i++){
            double ci=c[i+1];
            vp+=ci*st[i];
            vf+=ci*f_rev[i];
            vx+=ci*x_rev[i];
        }
        double inv_delta = 1.0/(d0-vp);
        double eps_inv = (b[k]-vx)*inv_delta;
        double vf_inv = vf*inv_delta;

        for (int j=0;j<k;j++){
            double sr=st_rev[j];
            x[j]-=eps_inv*sr;
            f[j]+=vf_inv*sr;
            buf[j]=x_rev[j]-eps_inv*st[j];
        }
        x[k]=eps_inv; x_rev[0]=eps_inv;
        for (int j=0;j<k;j++) x_rev[j+1]=buf[j];

        for (int j=0;j<k;j++) buf[j]=f_rev[j]+vf_inv*st[j];
        f[k]=-vf_inv; f_rev[0]=-vf_inv;
        for (int j=0;j<k;j++) f_rev[j+1]=buf[j];

        if (k<n-1){
            double vst=0;
            for (int i=0;i<k;i++) vst+=r[i+1]*st_rev[i];
            double gamma_t=r[k+1]-vst;
            for (int j=0;j<k;j++){
                buf[j]=st_rev[j]+gamma_t*f[j+1];
                st[j]+=gamma_t*f_rev[j];
            }
            st[k]=gamma_t*f[0];
            st_rev[0]=st[k];
            for (int j=0;j<k;j++) st_rev[j+1]=buf[j];
        }
    }
    free(f);free(st);free(st_rev);free(f_rev);free(x_rev);free(buf);
}
