#include <stdlib.h>
#include <math.h>

/*
 * Nonsymmetric Levinson in predictor form, all loops contiguous and forward.
 * Arrays (length n), at stage m (current order, size m, indices 0..m-1 valid):
 *   a[0]=1, a[1..m-1] forward predictor; we store a so that
 *   the Yule-Walker holds and updates are saxpys.
 *
 * Instead, keep the validated formulation but arrange memory so clang
 * vectorizes. The key cost is the per-step shift of reversed arrays.
 * Replace reversed-array maintenance by storing st in REVERSE order only
 * and computing the forward dot via a reversed c. 
 *
 * Layout chosen here (validated algorithm, memory-optimized):
 *   st_rev[j] = st[k-1-j]  (maintained)
 *   We do NOT keep f_rev, x_rev. Instead f and x are updated in normal order
 *   and we compute the two reversed dots by iterating c backward against f,x
 *   forward — but that was slow. 
 *
 * New: store f and x in normal order AND accept the reverse copy, but fuse
 * the reverse-copy with the dot using a pointer that walks backward while the
 * other walks forward — clang can vectorize a backward sequential scan.
 * Test that hypothesis with __builtin_prefetch and pragma simd.
 */
void solve_toep(const double* __restrict c, const double* __restrict r,
                const double* __restrict b, double* __restrict x, int n) {
    double* __restrict f = (double*)malloc((size_t)n*sizeof(double));
    double* __restrict st = (double*)malloc((size_t)n*sizeof(double));
    double* __restrict st_rev = (double*)malloc((size_t)n*sizeof(double));
    double* __restrict f_rev = (double*)malloc((size_t)n*sizeof(double));
    double* __restrict x_rev = (double*)malloc((size_t)n*sizeof(double));
    double* __restrict buf = (double*)malloc((size_t)n*sizeof(double));

    double d0 = r[0];
    x[0] = b[0]/d0;
    f[0] = 1.0/d0;
    if (n==1) goto done;
    st[0] = r[1]/d0;
    st_rev[0]=st[0]; f_rev[0]=f[0]; x_rev[0]=x[0];

    for (int k=1; k<n; ++k){
        double vp=0.0, vf=0.0, vx=0.0;
        const double* ck = c+1;
        #pragma omp simd reduction(+:vp,vf,vx)
        for (int i=0;i<k;++i){
            double ci = ck[i];
            vp += ci*st[i];
            vf += ci*f_rev[i];
            vx += ci*x_rev[i];
        }
        double inv_delta = 1.0/(d0-vp);
        double eps_inv = (b[k]-vx)*inv_delta;
        double vf_inv = vf*inv_delta;

        #pragma omp simd
        for (int j=0;j<k;++j){
            double sr = st_rev[j];
            x[j] -= eps_inv*sr;
            f[j] += vf_inv*sr;
            buf[j] = x_rev[j] - eps_inv*st[j];
        }
        x[k]=eps_inv; x_rev[0]=eps_inv;
        #pragma omp simd
        for (int j=0;j<k;++j) x_rev[j+1]=buf[j];

        #pragma omp simd
        for (int j=0;j<k;++j) buf[j]=f_rev[j]+vf_inv*st[j];
        f[k]=-vf_inv; f_rev[0]=-vf_inv;
        #pragma omp simd
        for (int j=0;j<k;++j) f_rev[j+1]=buf[j];

        if (k<n-1){
            double vst=0.0;
            const double* rk = r+1;
            #pragma omp simd reduction(+:vst)
            for (int i=0;i<k;++i) vst += rk[i]*st_rev[i];
            double gamma_t = r[k+1]-vst;
            #pragma omp simd
            for (int j=0;j<k;++j){
                buf[j] = st_rev[j] + gamma_t*f[j+1];
                st[j] += gamma_t*f_rev[j];
            }
            st[k] = gamma_t*f[0];
            st_rev[0] = st[k];
            #pragma omp simd
            for (int j=0;j<k;++j) st_rev[j+1]=buf[j];
        }
    }
done:
    free(f);free(st);free(st_rev);free(f_rev);free(x_rev);free(buf);
}
