#include <stdlib.h>

static inline double dot_rev(const double* __restrict a, const double* __restrict v, int k, int kk) {
    /* sum a[i+1]*v[kk-i], i=0..k-1, Kahan */
    double s = 0.0, comp = 0.0;
    for (int i = 0; i < k; ++i) {
        double y = a[i + 1] * v[kk - i] - comp;
        double t = s + y;
        comp = (t - s) - y;
        s = t;
    }
    return s;
}

static inline double dot_fwd(const double* __restrict a, const double* __restrict v, int k) {
    double s = 0.0, comp = 0.0;
    for (int i = 0; i < k; ++i) {
        double y = a[i + 1] * v[i] - comp;
        double t = s + y;
        comp = (t - s) - y;
        s = t;
    }
    return s;
}

void solve_toep(const double* __restrict c, const double* __restrict r,
                const double* __restrict b, double* __restrict x, int n) {
    double* __restrict f  = (double*)malloc((size_t)n * sizeof(double));
    double* __restrict st = (double*)malloc((size_t)n * sizeof(double));
    double d0 = r[0];
    x[0] = b[0] / d0;
    f[0] = 1.0 / d0;
    if (n == 1) { free(f); free(st); return; }
    st[0] = r[1] / d0;

    for (int k = 1; k < n; ++k) {
        int kk = k - 1;
        double vp = dot_fwd(c, st, k);
        double vf = dot_rev(c, f, k, kk);
        double vx = dot_rev(c, x, k, kk);
        double inv_delta = 1.0 / (d0 - vp);
        double eps_inv = (b[k] - vx) * inv_delta;
        double vf_inv = vf * inv_delta;
        for (int j = 0; j < k; ++j) {
            double s = st[kk - j];
            x[j] -= eps_inv * s;
            f[j] += vf_inv * s;
        }
        x[k] = eps_inv;
        f[k] = -vf_inv;
        if (k < n - 1) {
            double vst = dot_rev(r, st, k, kk);
            double gamma_t = r[k + 1] - vst;
            for (int j = 0; j < k; ++j) st[j] += gamma_t * f[k - j];
            st[k] = gamma_t * f[0];
        }
    }
    free(f); free(st);
}
